export function exposeApplicationPorts(target, applications) {
  Object.defineProperties(target, {
    ...Object.fromEntries(
      Object.entries(APPLICATION_FIELDS).map(([name, owner]) => [
        name,
        {
          enumerable: true,
          get: () => applications[owner][name],
          // Only trusted host state replacement and the externally controlled story lock are writable.
          ...(["state", "storyBusy"].includes(name)
            ? {
                set: (value) => {
                  applications[owner][name] = value;
                },
              }
            : {}),
        },
      ]),
    ),
    ...Object.fromEntries(
      Object.entries(APPLICATION_METHODS).map(([name, [owner, method]]) => {
        const invoke = (...args) => applications[owner][method](...args);
        // Accessors allow the UI command proxy to supply its validated route without violating Proxy invariants.
        return [name, { get: () => invoke }];
      }),
    ),
    actors: { get: () => applications.actors.api },
    actorRuntime: { get: () => applications.actors.runtime },
  });
}
